    http_client: Client,
    base_url: String,
    is_official_service: bool,
    cache_namespace: String,
    last_time_entry_mutation: std::sync::Arc<std::sync::Mutex<Option<i64>>>,
    last_related_mutation: std::sync::Arc<std::sync::Mutex<std::collections::HashMap<String, i64>>>,
