                as Box<dyn std::error::Error + Send>),
            Ok(response) => {
                let status = response.status();
                let body = response.text().await.map_err(|error| {
                    Box::new(ApiError::NetworkWithMessage(error.to_string()))
                        as Box<dyn std::error::Error + Send>
                })?;

                if !status.is_success() {
