pub struct BillCommand;

fn rounded_duration_seconds(duration: i64) -> i64 {
    ((duration + 899) / 900) * 900
}

fn aggregate(entries: impl IntoIterator<Item = TimeEntry>) -> Vec<(String, i64)> {
    let mut totals: HashMap<String, i64> = HashMap::new();

    for entry in entries {
        if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
            continue;
        }

        let project = entry
            .project
            .map(|project| project.name)
            .unwrap_or_else(|| constants::NO_PROJECT.to_string());
        *totals.entry(project).or_default() += rounded_duration_seconds(entry.duration);
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
        right_seconds
            .cmp(left_seconds)
            .then_with(|| left_name.cmp(right_name))
    });
    totals
}

fn format_output(totals: &[(String, i64)]) -> String {
    if totals.is_empty() {
        return "(no data)\n".to_string();
    }

    let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
    let mut output = String::new();
    for (project, seconds) in totals {
        output.push_str(&format!("{seconds}s  {project}\n"));
    }
    output.push_str(&format!("{total_seconds}s  Total\n"));
    output
}

impl BillCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let entries = if since.is_some() || until.is_some() {
            let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
            api_client.get_time_entries_filtered(since, until).await?
        } else {
            api_client.get_entities().await?.time_entries
        };

        let output = format_output(&aggregate(entries));
        io::stdout().write_all(output.as_bytes())?;
        Ok(())
    }
}

